create extension if not exists "pgcrypto";
create type public.app_role as enum ('user','analyst','admin');
create type public.alert_severity as enum ('LOW','MEDIUM','HIGH','CRITICAL');
create type public.source_status as enum ('CONNECTED','DEGRADED','DISCONNECTED','DEMO');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, role public.app_role not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.countries (id uuid primary key default gen_random_uuid(), code text not null unique check (char_length(code) = 2), name text not null unique, region text, created_at timestamptz not null default now());
create table public.trend_sources (id uuid primary key default gen_random_uuid(), name text not null unique, provider_type text not null, status public.source_status not null default 'DEMO', last_success_at timestamptz, config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.trends (id uuid primary key default gen_random_uuid(), source_id uuid references public.trend_sources(id), country_id uuid references public.countries(id), title text not null, keyword text not null, category text not null, region text, popularity numeric not null check (popularity >= 0), previous_popularity numeric not null default 0 check (previous_popularity >= 0), change_percentage numeric, velocity numeric, sentiment text check (sentiment in ('Positive','Neutral','Negative')), confidence numeric check (confidence between 0 and 100), score numeric check (score between 0 and 100), captured_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.trend_snapshots (id uuid primary key default gen_random_uuid(), trend_id uuid not null references public.trends(id) on delete cascade, popularity numeric not null check (popularity >= 0), engagement numeric check (engagement >= 0), sentiment_score numeric check (sentiment_score between -1 and 1), captured_at timestamptz not null default now());
create table public.trend_mentions (id uuid primary key default gen_random_uuid(), trend_id uuid not null references public.trends(id) on delete cascade, source_url text, external_id text, published_at timestamptz, sentiment_score numeric check (sentiment_score between -1 and 1), engagement numeric check (engagement >= 0), unique (trend_id, external_id));
create table public.economic_indicators (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, unit text not null, frequency text not null, source_id uuid references public.trend_sources(id), created_at timestamptz not null default now());
create table public.economic_observations (id uuid primary key default gen_random_uuid(), indicator_id uuid not null references public.economic_indicators(id) on delete cascade, country_id uuid not null references public.countries(id), value numeric not null, observed_on date not null, source_url text, created_at timestamptz not null default now(), unique(indicator_id, country_id, observed_on));
create table public.ai_insights (id uuid primary key default gen_random_uuid(), trend_id uuid references public.trends(id) on delete set null, user_id uuid references auth.users(id) on delete set null, title text not null, summary text not null, fact text not null, signal text not null, interpretation text not null, risk public.alert_severity not null, opportunity public.alert_severity not null, confidence numeric check (confidence between 0 and 100), model_name text, is_system_generated boolean not null default true, created_at timestamptz not null default now());
create table public.predictions (id uuid primary key default gen_random_uuid(), trend_id uuid references public.trends(id) on delete set null, prediction text not null, probability numeric not null check (probability between 0 and 100), timeframe text not null, supporting_signals jsonb not null default '[]'::jsonb, uncertainty text not null, model_name text, created_at timestamptz not null default now());
create table public.watchlists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, position int not null default 0 check (position >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, name));
create table public.watchlist_items (id uuid primary key default gen_random_uuid(), watchlist_id uuid not null references public.watchlists(id) on delete cascade, item_type text not null check (item_type in ('trend','country','indicator','keyword','market')), item_id uuid, keyword text, position int not null default 0 check (position >= 0), alert_config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check (item_id is not null or keyword is not null));
create table public.alerts (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, trend_id uuid references public.trends(id) on delete set null, indicator_id uuid references public.economic_indicators(id) on delete set null, title text not null, description text not null, type text not null, severity public.alert_severity not null, recommended_action text, read_at timestamptz, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, alert_id uuid references public.alerts(id) on delete cascade, channel text not null default 'in_app', delivered_at timestamptz, read_at timestamptz, created_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references auth.users(id) on delete cascade, theme text not null default 'dark', refresh_interval_minutes int not null default 15 check (refresh_interval_minutes between 5 and 1440), notification_preferences jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.data_source_status (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.trend_sources(id) on delete cascade, status public.source_status not null, message text, checked_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index trends_rank_idx on public.trends(score desc, captured_at desc); create index trend_snapshots_history_idx on public.trend_snapshots(trend_id, captured_at desc); create index economic_observations_series_idx on public.economic_observations(indicator_id, country_id, observed_on desc); create index alerts_user_unread_idx on public.alerts(user_id, created_at desc) where read_at is null; create index watchlists_user_idx on public.watchlists(user_id, position); create index audit_logs_created_idx on public.audit_logs(created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security invoker set search_path = '' as $$ select exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') $$;
create or replace function public.create_profile_for_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, display_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1))); insert into public.user_settings(user_id) values (new.id); return new; end; $$;
revoke execute on function public.create_profile_for_user() from public;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile_for_user();
alter table public.profiles enable row level security; alter table public.countries enable row level security; alter table public.trend_sources enable row level security; alter table public.trends enable row level security; alter table public.trend_snapshots enable row level security; alter table public.trend_mentions enable row level security; alter table public.economic_indicators enable row level security; alter table public.economic_observations enable row level security; alter table public.ai_insights enable row level security; alter table public.predictions enable row level security; alter table public.watchlists enable row level security; alter table public.watchlist_items enable row level security; alter table public.alerts enable row level security; alter table public.notifications enable row level security; alter table public.user_settings enable row level security; alter table public.data_source_status enable row level security; alter table public.audit_logs enable row level security;
create policy "profile owner reads" on public.profiles for select to authenticated using ((select auth.uid()) = id or (select public.is_admin())); create policy "profile owner updates" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy "system data readable" on public.countries for select to authenticated using (true); create policy "system data readable" on public.trend_sources for select to authenticated using (true); create policy "system data readable" on public.trends for select to authenticated using (true); create policy "system data readable" on public.trend_snapshots for select to authenticated using (true); create policy "system data readable" on public.trend_mentions for select to authenticated using (true); create policy "system data readable" on public.economic_indicators for select to authenticated using (true); create policy "system data readable" on public.economic_observations for select to authenticated using (true); create policy "system data readable" on public.predictions for select to authenticated using (true); create policy "system data readable" on public.data_source_status for select to authenticated using (true);
create policy "insights visible when public or owner" on public.ai_insights for select to authenticated using (is_system_generated or user_id = (select auth.uid()) or (select public.is_admin()));
create policy "watchlist owners manage" on public.watchlists for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy "watchlist item owners manage" on public.watchlist_items for all to authenticated using (exists(select 1 from public.watchlists w where w.id = watchlist_id and w.user_id = (select auth.uid()))) with check (exists(select 1 from public.watchlists w where w.id = watchlist_id and w.user_id = (select auth.uid())));
create policy "alert owners read" on public.alerts for select to authenticated using (user_id = (select auth.uid()) or (select public.is_admin())); create policy "alert owners update" on public.alerts for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy "notification owners manage" on public.notifications for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy "settings owner manages" on public.user_settings for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy "admins audit read" on public.audit_logs for select to authenticated using ((select public.is_admin()));
grant usage on schema public to anon, authenticated; grant select on public.countries, public.trend_sources, public.trends, public.trend_snapshots, public.trend_mentions, public.economic_indicators, public.economic_observations, public.predictions, public.data_source_status to authenticated; grant select, update on public.profiles, public.alerts to authenticated; grant select, insert, update, delete on public.watchlists, public.watchlist_items, public.notifications, public.user_settings to authenticated;
